#!/bin/sh
# Generated by forge. Stop hook: runs .forge/check.sh on what changed during this
# turn (--turn, against the snapshot taken by turn-start.sh), or on every
# uncommitted change when there is no snapshot (--changed); hands over after 3 blocks.
# A tree that failed is not checked again: the same reason is given until it changes.
dir=$(cd "$(dirname "$0")" && pwd)
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
repo_root || exit 0
[ -f .forge/check.sh ] || { printf '{"decision":"block","reason":"forge:forge/integrity .forge/check.sh is missing (run forge apply)"}\n'; exit 0; }
mkdir -p .forge/state 2>/dev/null

counter=.forge/state/$(session_id).blocks
snap=$(turn_dir)
hash=$(tree_hash)
if [ -f "$snap/head" ]; then
  # unchanged since the prompt (same tree, same HEAD): whatever is dirty is not this turn's work
  [ "$hash" = "$(cat "$snap/tree" 2>/dev/null)" ] && [ "$(git rev-parse -q --verify HEAD 2>/dev/null)" = "$(cat "$snap/head")" ] && exit 0
  passed=$snap/pass
  failed=$snap/fail
  hash="$hash $(git rev-parse -q --verify HEAD 2>/dev/null)"
  set -- --turn "$snap"
else
  passed=.forge/state/last-pass
  failed=.forge/state/last-fail
  set -- --changed
fi
[ "$hash" = "$(cat "$passed" 2>/dev/null)" ] && exit 0

count=$(cat "$counter" 2>/dev/null)
case $count in ''|*[!0-9]*) count=0 ;; esac
if [ "$count" -ge 3 ]; then
  rm -f "$counter"
  printf '{"systemMessage":"forge: check failed 3 times. Handing over to you."}\n'
  exit 0
fi

# the tree as it is now (after formatters ran)
now_tree() { if [ -f "$snap/head" ]; then printf '%s %s\n' "$(tree_hash)" "$(git rev-parse -q --verify HEAD 2>/dev/null)"; else tree_hash; fi; }
# block [<first line>]: blocks with the reason in $failed.reason
block() {
  printf '%s\n' "$((count + 1))" > "$counter"
  printf '{"decision":"block","reason":"%s"}\n' "$({ [ -z "${1:-}" ] || printf '%s\n' "$1"; cat "$failed.reason"; } | json_escape)"
  exit 0
}

# Same tree as the last failed check: the checks give the same result on the same
# tree, so it is given again without re-running them (a test suite can take minutes).
if [ "$hash" = "$(cat "$failed" 2>/dev/null)" ] && [ -f "$failed.reason" ]; then
  block 'forge: nothing changed in the working tree since this check failed, so it was not run again (it runs again once a file changes):'
fi

out=$(sh .forge/check.sh "$@" 2>&1)
if [ $? -eq 0 ]; then
  now_tree > "$passed"
  rm -f "$counter" "$failed" "$failed.reason"
  exit 0
fi
# the failures first, then the "skipped" and "ok for" notes; at most 40 lines and
# 6000 characters, so the reason stays short when Claude Code shows it
printf '%s\n' "$out" \
  | awk '/^forge:[^ ]+ (skipped:|ok for )/ { note[++k] = $0; next } { print } END { for (i = 1; i <= k; i++) print note[i] }' \
  | awk '{ c += length($0) + 1 } NR <= 40 && c <= 6000' > "$failed.reason"
now_tree > "$failed"
block
